package org.deposit.it;

import static org.junit.jupiter.api.Assertions.*;
import static org.deposit.it.Stage1LifecycleIT.*;
import java.util.*;
import java.nio.file.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.neo4j.driver.*;

/** Independent public-contract corpus. Expected values never call plugin helpers. */
@Timeout(120)
class Stage6CoreIT {
    static String token,second,ns,clazz,s1,s2,s3,c1,c2;static final List<String> trace=new ArrayList<>();
    @BeforeAll static void start(){connect();token=Stage3CoreIT.login();second=Stage3CoreIT.login();}
    @AfterAll static void finish()throws Exception{Files.writeString(Path.of(System.getenv("STAGE0_EVIDENCE")).resolve("stage6-corpus-actual.txt"),String.join("\n",trace));close();}
    @BeforeEach void seed(){Stage3CoreIT.token=token;Stage3CoreIT.second=second;new Stage3CoreIT().namespace();ns=Stage3CoreIT.namespace;
        clazz=id(change("deposit.create.class",m("name","Specimen","descriptors",List.of(m("name","Code","type","String"),m("name","Mass","type","Float"),m("name","N","type","Integer")))));
        String context=id(change("deposit.create.class",m("name","Context","descriptors",List.of(m("name","Code","type","String")))));
        s1=object(clazz,m("Code","S1","Mass",10.0,"N",10L));s2=object(clazz,m("Code","S2","Mass",20.0,"N",20L));s3=object(clazz,m("Code","S3"));c1=object(context,m("Code","C1"));c2=object(context,m("Code","C2"));edge(s1,c1,"foundIn");edge(s2,c1,"foundIn");trace.add("fixture "+m("ns",ns,"S1",s1,"S2",s2,"S3",s3,"C1",c1,"C2",c2));}
    static org.neo4j.driver.Record change(String p,Map<String,Object> r){return Stage3CoreIT.writeCall(p,r);}
    static String object(String c,Map<String,Object> d){return id(change("deposit.create.object",m("classId",c,"descriptors",d)));}
    static void edge(String a,String b,String label){change("deposit.create.relationship",m("sourceId",a,"targetId",b,"label",label));}
    static List<org.neo4j.driver.Record> q(String text){return q(text,Map.of());}
    static List<org.neo4j.driver.Record> q(String text,Map<String,Object> params){var result=query("CALL deposit.get.query($r,$c)",m("r",m("query",text,"parameters",params),"c",ctx(token)));trace.add(text+" parameters="+params+" => "+result);return result;}
    static org.neo4j.driver.Record page(Map<String,Object> r){return call("deposit.get.queryPage",r,ctx(token));}
    static void codes(String query,String... expected){var actual=q(query).stream().map(r->r.get("data").get("code").asString()).toList();trace.add("expected="+List.of(expected));assertEquals(List.of(expected),actual);}
    static void set(String id,String name,Object value){change("deposit.set.descriptor",m("objectId",id,"name",name,"value",value));}
    static void typed(String id,String name,String type,Object value){set(id,name,m("type",type,"value",value));}
    static List<Object> values(String text,String key){return q(text).stream().map(r->r.get("data").get(key).asObject()).toList();}
    @Test void documentedExamplesAndPrecedence(){codes("SELECT Specimen.Code AS code ORDER BY code","S1","S2","S3");codes("SELECT Specimen.Code AS code WHERE Specimen.Mass>10 ORDER BY code","S2");codes("SELECT Specimen.Code AS code WHERE NOT Specimen-foundIn->Context","S3");codes("SELECT Specimen.Code AS code WHERE Specimen.Mass IS MISSING","S3");codes("SELECT Specimen.Code AS code WHERE Specimen.Mass=10 OR Specimen.Mass=20 AND Specimen.Code='S1'","S1");codes("SELECT Specimen.Code AS code WHERE Specimen.Mass>5 AND code IN ['S1','S3']","S1");var grouped=q("SELECT Context.Code AS context,COUNT(Specimen) AS n WHERE Specimen-foundIn->Context");assertEquals(1,grouped.size());assertEquals("C1",grouped.getFirst().get("data").get("context").asString());assertEquals(2L,grouped.getFirst().get("data").get("n").asLong());assertEquals(2L,values("SELECT COUNT(Specimen) AS n WHERE Specimen-foundIn->Context","n").getFirst());}
    @Test void fixedAggregateResultsTypesAndEmptyInput(){var row=q("SELECT SUM(Specimen.Mass) AS total,AVG(Specimen.Mass) AS mean,MIN(Specimen.Mass) AS low,MAX(Specimen.Mass) AS high,STDEV(Specimen.Mass) AS spread,PERCENTILE(Specimen.Mass,0.25) AS q WHERE Specimen-foundIn->Context").getFirst();assertEquals(30.0,row.get("data").get("total").asDouble());assertEquals(15.0,row.get("data").get("mean").asDouble());assertEquals(10.0,row.get("data").get("low").asDouble());assertEquals(20.0,row.get("data").get("high").asDouble());assertEquals(Math.sqrt(50),row.get("data").get("spread").asDouble(),1e-12);assertEquals(12.5,row.get("data").get("q").asDouble());assertEquals("Float",row.get("columns").get(0).get("type").asString());
        var empty=q("SELECT COUNT(Specimen) AS n,SUM(Specimen.N) AS sum,AVG(Specimen.N) AS mean,STDEV(Specimen.N) AS sd WHERE Specimen.Code='absent'").getFirst();assertEquals(0L,empty.get("data").get("n").asLong());assertEquals(0L,empty.get("data").get("sum").asLong());assertTrue(empty.get("data").get("mean").isNull());assertEquals(0.0,empty.get("data").get("sd").asDouble());assertTrue(empty.get("presence").get("mean").asBoolean());assertEquals(0,q("SELECT Specimen.Code,COUNT(Specimen) AS n WHERE Specimen.Code='absent'").size());}
    @Test void independentAndSharedEndpointsAndNegation(){edge(s1,c2,"recordedIn");codes("SELECT Specimen.Code AS code WHERE Specimen-foundIn->Context AND Specimen-recordedIn->Context","S1");assertTrue(q("SELECT Specimen.Code,Context AS c WHERE Specimen-foundIn->c AND Specimen-recordedIn->c").isEmpty());assertEquals(2,q("SELECT Specimen.Code,Context AS c WHERE Specimen-foundIn->c AND NOT Specimen-recordedIn->c").size());assertEquals(0,q("SELECT Specimen.Code WHERE NOT Specimen-foundIn->Context AND Specimen.Code='S1'").size());}
    @Test void connectivitySameClassSelfEdgesAndBoundedTraversal(){edge(s1,s2,"relatedTo");edge(s2,s2,"relatedTo");assertEquals(2,q("SELECT Specimen AS a,Specimen AS b WHERE a-relatedTo->b").size());assertEquals(1,q("SELECT Specimen WHERE Specimen-relatedTo->Specimen").size());error("VALIDATION_FAILED",()->q("SELECT Specimen,Context WHERE Specimen-foundIn->Context OR Specimen.Code='S3'"));assertEquals(2,q("SELECT Specimen,Context").size());assertTrue(q("SELECT Specimen,Context WHERE Specimen-*1..2->Context").size()>=2);error("VALIDATION_FAILED",()->q("SELECT Specimen WHERE Specimen-*1..11->Context"));}
    @Test void missingNullDistinctAndGrouping(){set(s2,"Mass",null);change("deposit.set.object",m("id",s1,"clearDescriptors",List.of("Mass")));var distinct=q("SELECT DISTINCT Specimen.Mass AS mass");assertEquals(2,distinct.size());assertEquals(Set.of(false,true),new HashSet<>(distinct.stream().map(r->r.get("presence").get("mass").asBoolean()).toList()));var groups=q("SELECT Specimen.Mass AS mass,COUNT(Specimen) AS n");assertEquals(2,groups.size());assertEquals(3,groups.stream().mapToLong(r->r.get("data").get("n").asLong()).sum());codes("SELECT Specimen.Code AS code WHERE Specimen.Mass IS NULL AND Specimen.Mass IS NOT MISSING","S2");assertTrue(q("SELECT Specimen WHERE NOT Specimen.Mass=10").isEmpty());}
    @Test void parametersQuotingAndValidation(){String other=id(change("deposit.create.class",m("name","Sample set","descriptors",List.of(m("name","Dry mass","type","Float"),m("name","Sample code","type","String")))));object(other,m("Dry mass",10.0,"Sample code","X1"));assertEquals("X1",q("SELECT \"Sample set\".\"Sample code\" AS code WHERE \"Sample set\".\"Dry mass\">$minimum",m("minimum",5L)).getFirst().get("data").get("code").asString());String unicode="\u017dlu\u0165ou\u010dk\u00fd";String uc=id(change("deposit.create.class",m("name",unicode)));object(uc,Map.of());assertEquals(1,q("SELECT \""+unicode+"\"").size());assertTrue(q("SELECT Specimen WHERE Specimen.Code=$value",m("value","' MATCH (n) DETACH DELETE n //")).isEmpty());error("TYPE_CONFLICT",()->q("SELECT Specimen WHERE Specimen.Mass=$x AND Specimen.Code=$x",m("x",10.0)));for(String text:List.of("SELECT Specimen trailing","SELECT Specimen AS a,Specimen AS a","SELECT Specimen WHERE Specimen.Mass IN (10,20)","SELECT Specimen WHERE Specimen.Mass=$missing"))error("VALIDATION_FAILED",()->q(text));error("NOT_FOUND",()->q("SELECT Unknown"));}
    @Test void collectRowsDuplicatesNullsAndEmptyColumns(){set(s2,"Mass",10.0);assertEquals(List.of(10.0,10.0),values("SELECT COLLECT(Specimen.Mass) AS mass","mass"));assertEquals(List.of(10.0),values("SELECT COLLECT(DISTINCT Specimen.Mass) AS mass","mass"));assertTrue(q("SELECT COLLECT(Specimen.Mass) AS mass WHERE Specimen.Code='S3'").isEmpty());var empty=page(m("query","SELECT COLLECT(Specimen.Mass) AS mass WHERE Specimen.Code='S3'"));assertEquals(0,empty.get("data").get("rows").size());assertEquals("Float",empty.get("data").get("columns").get(0).get("type").asString());error("VALIDATION_FAILED",()->q("SELECT COLLECT(Specimen.Mass) AS mass,Specimen.Code"));error("VALIDATION_FAILED",()->q("SELECT COLLECT(Specimen) AS object"));}
    @Test void everyDescriptorTypeCollectAndStructuralEquality(){var examples=new LinkedHashMap<String,Object>();examples.put("String","text");examples.put("Integer",Long.MAX_VALUE);examples.put("Float",2.5);examples.put("Boolean",true);examples.put("Date","2026-10-09");examples.put("Time","12:34:56+02:00");examples.put("LocalTime","12:34:56");examples.put("DateTime","2026-10-09T12:34:56+02:00");examples.put("LocalDateTime","2026-10-09T12:34:56");examples.put("Duration",duration(1,2,3,4));examples.put("Point",m("srid",7203L,"coordinates",List.of(1.0,2.0)));examples.put("List",m("itemType","Integer","items",Arrays.asList(Long.MAX_VALUE,null,2L)));examples.put("DDict",m("b",m("type","Integer","value",2L),"a",m("type","String","value","a")));examples.put("DGeometry",Stage4CoreIT.geometry("POINT (1 2)",null,2));Stage4CoreIT.token=token;Stage4CoreIT.ns=ns;Stage4CoreIT.object=s1;examples.put("DResource",m("resourceId",Stage4CoreIT.upload(Stage4CoreIT.ABC,"query.txt")));
        for(var e:examples.entrySet()){String name="V"+e.getKey();typed(s1,name,e.getKey(),e.getValue());var result=q("SELECT COLLECT(Specimen."+name+") AS value");assertEquals(1,result.size(),name);assertEquals(e.getKey(),result.getFirst().get("columns").get(0).get("type").asString());assertEquals(e.getValue(),result.getFirst().get("data").get("value").asObject(),name);assertEquals(1,q("SELECT Specimen WHERE Specimen."+name+"=$value",m("value",e.getValue())).size(),name);}
        for(String type:List.of("Point","List","DDict","DGeometry","DResource")){error("TYPE_CONFLICT",()->q("SELECT Specimen.V"+type+" ORDER BY Specimen.V"+type));error("TYPE_CONFLICT",()->q("SELECT MIN(Specimen.V"+type+") AS x"));}}
    static Map<String,Object> duration(long months,long days,long seconds,long nanos){return m("months",months,"days",days,"seconds",seconds,"nanoseconds",nanos);}
    @Test void durationAndTemporalSemanticOrdering(){typed(s1,"Elapsed","Duration",duration(1,0,0,0));set(s2,"Elapsed",duration(0,30,0,0));set(s3,"Elapsed",duration(0,0,-1,0));assertEquals(List.of("S3","S2","S1"),q("SELECT Specimen.Code AS code,Specimen.Elapsed AS elapsed ORDER BY elapsed").stream().map(r->r.get("data").get("code").asString()).toList());assertEquals(1,q("SELECT Specimen WHERE Specimen.Elapsed>$d",m("d",duration(0,30,0,1))).size());assertEquals(duration(0,0,-1,0),q("SELECT MIN(Specimen.Elapsed) AS d").getFirst().get("data").get("d").asMap());typed(s1,"Time","DateTime","2026-10-09T10:00:00Z");set(s2,"Time","2026-10-09T11:00:00+02:00");assertEquals("S2",q("SELECT Specimen.Code AS code,Specimen.Time AS time ORDER BY time").getFirst().get("data").get("code").asString());}
    @Test void duplicatesCyclesAndNativeComposition(){edge(s1,s2,"via");edge(s2,s1,"via");assertEquals(2L,q("SELECT COUNT(Specimen) AS n WHERE Specimen-*1..3->Context").getFirst().get("data").get("n").asLong());assertEquals(30.0,q("SELECT SUM(Specimen.Mass) AS n WHERE Specimen-*1..3->Context").getFirst().get("data").get("n").asDouble());assertEquals(1L,q("SELECT COUNT(DISTINCT Context) AS n WHERE Specimen-foundIn->Context AND Specimen.Mass>0").getFirst().get("data").get("n").asLong());var nativeRows=query("CALL deposit.get.query({query:'SELECT Specimen AS s WHERE Specimen.Mass>5'},$c) YIELD data WITH data.s AS s MATCH (s)-[:MEMBER_OF]->(cl:Class) RETURN count(*) AS n",m("c",ctx(token)));assertEquals(2L,nativeRows.getFirst().get("n").asLong());assertEquals(30.0,query("CALL deposit.get.query({query:'SELECT Specimen.Mass AS mass'},$c) YIELD data RETURN sum(data.mass) AS total",m("c",ctx(token))).getFirst().get("total").asDouble());}
    @Test void namespaceHistoryAndRelationshipLabelIsolation(){String original=ns;change("deposit.set.versioningType",m("mode","persistent"));set(s1,"Mass",999.0);set(s1,"Mass",10.0);assertEquals(3,q("SELECT Specimen").size());String other=id(call("deposit.create.namespace",m("name","other-"+UUID.randomUUID()),write(token,Stage3CoreIT.server())));Stage3CoreIT.select(token,other);String cl=id(change("deposit.create.class",m("name","Specimen")));object(cl,Map.of());assertEquals(1,q("SELECT Specimen").size());Stage3CoreIT.select(token,original);assertEquals(3,q("SELECT Specimen").size());assertEquals(2,q("SELECT Specimen WHERE Specimen-foundIn->Context").size());assertEquals(0,query("MATCH ()-[r:MEMBER_OF|RELATED_TO {namespaceId:$ns}]->() WHERE r.kind IS NOT NULL RETURN r",m("ns",original)).size());}
    static void bulk(){for(int batch=0;batch<2;batch++){var commands=new ArrayList<Map<String,Object>>();for(int i=0;i<550;i++)commands.add(Stage3CoreIT.command("x"+i,"deposit.create.object",m("classId",clazz,"descriptors",m("Code","B"+(batch*550+i),"Mass",1.0))));Stage3CoreIT.batch(commands);}}
    @Test void completeStreamsPagesAndMixedOrdering(){
        bulk();String text="SELECT Specimen.Code AS code,Specimen.Mass AS mass ORDER BY mass DESC,code";var stream=q(text);assertEquals(1103,stream.size());var objects=page(m("query","SELECT Specimen AS s","pageSize",2L));assertEquals("Object",objects.get("data").get("columns").get(0).get("type").asString());assertEquals(q("SELECT Specimen AS s").getFirst().get("data").get("s").asNode().get("id").asString(),objects.get("data").get("rows").get(0).get("values").get("s").get("id").asString());assertTrue(stream.getLast().get("data").get("mass").isNull());
        var expectedColumns=stream.getFirst().get("columns").asList(value->value.asMap());var expected=stream.stream().map(row->row.get("data").asMap()).toList();var expectedPresence=stream.stream().map(row->row.get("presence").asMap()).toList();var all=new ArrayList<Map<String,Object>>();var allPresence=new ArrayList<Map<String,Object>>();String cursor=null;
        do{var r=m("query",text,"pageSize",137L);if(cursor!=null)r.put("cursor",cursor);var current=page(r);assertEquals(expectedColumns,current.get("data").get("columns").asList(value->value.asMap()));for(Value row:current.get("data").get("rows").values()){all.add(row.get("values").asMap());allPresence.add(row.get("presence").asMap());}cursor=current.get("meta").get("nextCursor").asString(null);}while(cursor!=null);
        assertEquals(expected,all);assertEquals(expectedPresence,allPresence);assertEquals(1103L,query("CALL deposit.get.query({query:'SELECT Specimen AS s'},$c) YIELD data RETURN count(data.s) AS n",m("c",ctx(token))).getFirst().get("n").asLong());error("VALIDATION_FAILED",()->call("deposit.get.query",m("query","SELECT Specimen","pageSize",1L),ctx(token)));
    }
    @Test void cursorScopeRevisionAndRequestBinding(){String text="SELECT Specimen.Code AS code";String cursor=page(m("query",text,"pageSize",1L)).get("meta").get("nextCursor").asString();error("VALIDATION_FAILED",()->page(m("query",text,"cursor",cursor+"bad")));error("VALIDATION_FAILED",()->page(m("query",text,"cursor",expiredCursor(cursor))));error("VALIDATION_FAILED",()->page(m("query","SELECT Specimen.Mass AS mass","cursor",cursor)));Stage3CoreIT.select(token,nullNamespace());error("SCOPE_MISMATCH",()->page(m("query",text,"cursor",cursor)));Stage3CoreIT.select(token,ns);set(s1,"Mass",11.0);error("REVISION_CONFLICT",()->page(m("query",text,"cursor",cursor)));}
    static String expiredCursor(String cursor){try{String body=new String(Base64.getUrlDecoder().decode(cursor.split("\\.")[0]),java.nio.charset.StandardCharsets.UTF_8).replaceAll("\"expires\":[0-9]+","\"expires\":0");String encoded=Base64.getUrlEncoder().withoutPadding().encodeToString(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));Path key;try(var files=Files.list(Stage0Paths.secretRoot())){key=files.filter(p->p.getFileName().toString().endsWith("-cursor.key")).findFirst().orElseThrow();}var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(Base64.getUrlDecoder().decode(Files.readString(key).trim()),"HmacSHA256"));return encoded+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(encoded.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new RuntimeException(e);}}
    static String nullNamespace(){return id(call("deposit.create.namespace",m("name","switch-"+UUID.randomUUID()),write(token,Stage3CoreIT.server())));}
    @Test void overflowAndPublicCatalog(){set(s1,"N",Long.MAX_VALUE);set(s2,"N",1L);error("LIMIT_EXCEEDED",()->q("SELECT SUM(Specimen.N) AS n"));var rows=query("SHOW PROCEDURES YIELD name,signature WHERE name IN ['deposit.get.query','deposit.get.queryPage'] RETURN name,signature",Map.of());assertEquals(2,rows.size());assertTrue(rows.stream().filter(r->r.get("name").asString().equals("deposit.get.query")).findFirst().orElseThrow().get("signature").asString().contains("presence :: MAP"));}
    @Test void viewerAuthorizationAndCursorReauthentication(){String username="query-viewer-"+UUID.randomUUID();String user=id(call("deposit.create.user",m("username",username,"password",PASSWORD),write(token,Stage3CoreIT.server())));change("deposit.set.namespaceRole",m("userId",user,"role","viewer"));String viewer=special("deposit.utils.login",m("username",username,"password",PASSWORD)).get("value").asString();error("NO_ACTIVE_NAMESPACE",()->call("deposit.get.queryPage",m("query","SELECT Specimen"),ctx(viewer)));Stage3CoreIT.select(viewer,ns);var r=m("query","SELECT Specimen.Code AS code ORDER BY code","pageSize",1L);var first=call("deposit.get.queryPage",r,ctx(viewer));String cursor=first.get("meta").get("nextCursor").asString();String renewed=special("deposit.utils.login",m("username",username,"password",PASSWORD)).get("value").asString();Stage3CoreIT.select(renewed,ns);r.put("cursor",cursor);assertEquals("S2",call("deposit.get.queryPage",r,ctx(renewed)).get("data").get("rows").get(0).get("values").get("code").asString());error("VALIDATION_FAILED",()->call("deposit.get.queryPage",r,ctx(token)));change("deposit.set.namespaceRole",m("userId",user,"role",null));error("NOT_FOUND",()->call("deposit.get.queryPage",r,ctx(viewer)));error("AUTH_FAILED",()->call("deposit.get.queryPage",m("query","SELECT Specimen"),ctx("invalid-token")));}
    @Test void decodingFailureRollsBackAndForeignPathsAreExcluded(){String bad="invalid-integer";query("MATCH (o:Object {id:$id})-[:HAS_DESCRIPTOR]->(d:Descriptor {name:'N'}) SET d.value=$bad",m("id",s1,"bad",bad));String marker=UUID.randomUUID().toString();assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->query("CREATE (:Stage6Rollback {id:$marker}) WITH 1 AS x CALL deposit.get.query({query:'SELECT Specimen.N AS n'},$c) YIELD data RETURN data",m("marker",marker,"c",ctx(token))));assertEquals(0,query("MATCH (n:Stage6Rollback {id:$marker}) RETURN n",m("marker",marker)).size());query("MATCH (o:Object {id:$id})-[:HAS_DESCRIPTOR]->(d:Descriptor {name:'N'}) SET d.value=10",m("id",s1));
        query("MATCH (s:Object {id:$s}),(c:Object {id:$c}) CREATE (f:Object:DepositLive {id:$id,namespaceId:'foreign'}),(s)-[:RELATED_TO {namespaceId:$ns,label:'bridge'}]->(f),(f)-[:RELATED_TO {namespaceId:$ns,label:'bridge'}]->(c)",m("s",s3,"c",c2,"id",UUID.randomUUID().toString(),"ns",ns));try{assertTrue(q("SELECT Specimen.Code WHERE Specimen.Code='S3' AND Specimen-*1..3->Context").isEmpty());}finally{query("MATCH (s:Object {id:$s})-[:RELATED_TO]->(f:Object {namespaceId:'foreign'}) DETACH DELETE f",m("s",s3));}}
    @Test void cancellationTimeoutAndEarlyConsumerCleanup()throws Exception{bulk();String expensive="SELECT Specimen AS a,Specimen AS b WHERE NOT a-unrelated->b";String request=UUID.randomUUID().toString();try(var pool=Executors.newSingleThreadExecutor()){var started=new CountDownLatch(1);var future=pool.submit(()->{started.countDown();return query("CALL deposit.get.query($r,$c)",m("r",m("query",expensive),"c",m("token",token,"requestId",request)));});assertTrue(started.await(5,TimeUnit.SECONDS));boolean cancelled=false;long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(!cancelled&&System.nanoTime()<until){cancelled=call("deposit.utils.cancel",m("requestId",request),ctx(token)).get("value").asBoolean();if(!cancelled)Thread.sleep(20);}assertTrue(cancelled);assertThrows(ExecutionException.class,()->future.get(10,TimeUnit.SECONDS));}
        error("LIMIT_EXCEEDED",()->call("deposit.get.query",m("query",expensive,"timeoutMs",1L),ctx(token)));
        assertEquals(1,query("CALL deposit.get.query({query:'SELECT Specimen AS s'},$c) YIELD data RETURN data LIMIT 1",m("c",ctx(token))).size());assertEquals(1103,q("SELECT Specimen").size());}
    @Test void streamRevisionFailureAndCapturedSelection(){bulk();try(var session=driver.session(SessionConfig.builder().withFetchSize(1).build());var tx=session.beginTransaction()){var result=tx.run("CALL deposit.get.query($r,$c)",m("r",m("query","SELECT Specimen.Code AS code"),"c",ctx(token)));assertTrue(result.hasNext());result.next();String other=nullNamespace();Stage3CoreIT.select(token,other);assertTrue(result.hasNext());Stage3CoreIT.select(token,ns);set(s1,"Mass",12.0);assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,result::list,"Remaining rows must detect the changed revision");tx.rollback();}}
}
